std::vector<Node> nodes;
nodes.reserve(rt.number_of_vertices());

for (auto it = rt.all_vertices_begin(); it != rt.all_vertices_end(); ++it) {
    if (rt.is_infinite(it)) continue;

    Node node;

    // Position
    node.position = it->point();

    // Velocity: In Regular Triangulations (CGAL), the vertex point often 
    // represents the weighted center. Velocity is typically derived from 
    // the change in position over time or stored in the vertex data.
    // Assuming standard Adhesion model where velocity is the point itself 
    // or derived from the dual space.
    node.velocity = it->point(); 

    // Mass: In the context of Adhesion/Regular Triangulations, 
    // the weight (weight = R^2) is often related to the mass/density.
    node.mass = it->weight();

    // Node Type Classification
    // A node is typically classified as a 'cluster' or 'filament' 
    // based on the length of the edges connected to it relative to a threshold.
    bool is_isolated = true;
    for (auto edge = rt.incident_edges(it), end = rt.all_edges_begin(); edge != end; ++edge) {
        if (rt.is_infinite(edge)) continue;

        double length = std::sqrt(std::pow(rt.vertex(edge->first)->point()[0] - rt.vertex(edge->second)->point()[0], 2) +
                                  std::pow(rt.vertex(edge->first)->point()[1] - rt.vertex(edge->second)->point()[1], 2) +
                                  std::pow(rt.vertex(edge->first)->point()[2] - rt.vertex(edge->second)->point()[2], 2));

        if (length < threshold) {
            is_isolated = false;
            break;
        }
    }

    node.type = is_isolated ? 0 : 1; // 0 for isolated/void, 1 for structure

    nodes.push_back(node);
}

return nodes;
// END_CODE

